window.registerChapter({"num": 60, "source_label": "60", "title": "Spinal Dysraphisms", "group": "Brain, neurology & development", "features": ["Prematurity", "Congenital anomaly", "Apnea", "Cardiac shunting", "Arrhythmia", "Infection / inflammation", "Developmental follow-up", "Skin findings", "Bone / joint", "Maternal / placental factors", "Family / comfort"], "pdf_start": 1149, "pdf_end": 1157, "printed_start": "1145", "printed_end": "1153", "figures": [{"path": "figures/ch060_p1150_01.jpg", "caption": "• Fig. 60.1 Meningocele—note the large fluid-filled sac protruding from the lumbar region. The skin edges terminate at the junction to the meninges.", "caption_matched": true, "pdf_page": 1150, "printed_page": "1146", "chapter": 60}, {"path": "figures/ch060_p1151_01.jpg", "caption": "• Fig. 60.2 Myelomeningocele—note the large central placode and open defect without an overlying meningeal sac.", "caption_matched": true, "pdf_page": 1151, "printed_page": "1147", "chapter": 60}, {"path": "figures/ch060_p1151_02.jpg", "caption": "• Fig. 60.3 Lipomyelomeningocele—the red arrow denotes the area of tethering of the subcutaneous lipoma to the neural placode.", "caption_matched": true, "pdf_page": 1151, "printed_page": "1147", "chapter": 60}, {"path": "figures/ch060_p1151_03.jpg", "caption": "• Fig. 60.3 Lipomyelomeningocele—the red arrow denotes the area of tethering of the subcutaneous lipoma to the neural placode.", "caption_matched": true, "pdf_page": 1151, "printed_page": "1147", "chapter": 60}, {"path": "figures/ch060_p1152_01.jpg", "caption": "• Fig. 60.4 Dermal sinus tract—similar to a lipomyelomeningocele but with an additional fibrous tract (red arrow) extending from a superficial skin dimple to the placode.", "caption_matched": true, "pdf_page": 1152, "printed_page": "1148", "chapter": 60}, {"path": "figures/ch060_p1152_02.jpg", "caption": "• Fig. 60.4 Dermal sinus tract—similar to a lipomyelomeningocele but with an additional fibrous tract (red arrow) extending from a superficial skin dimple to the placode.", "caption_matched": true, "pdf_page": 1152, "printed_page": "1148", "chapter": 60, "caption_match_method": "automatic page geometry, widened for shared multi-panel captions"}, {"path": "figures/ch060_p1152_03.jpg", "caption": "• Fig. 60.4 Dermal sinus tract—similar to a lipomyelomeningocele but with an additional fibrous tract (red arrow) extending from a superficial skin dimple to the placode.", "caption_matched": true, "pdf_page": 1152, "printed_page": "1148", "chapter": 60}, {"path": "figures/ch060_p1152_04.jpg", "caption": "• Fig. 60.4 Dermal sinus tract—similar to a lipomyelomeningocele but with an additional fibrous tract (red arrow) extending from a superficial skin dimple to the placode.", "caption_matched": true, "pdf_page": 1152, "printed_page": "1148", "chapter": 60}], "tables": [], "cards": 6, "summary": "Meningocele. In meningocele, meninges herniate but the spinal cord and roots remain within the canal.", "pillars": [{"label": "Contents of a spinal sac", "text": "Meningocele. In meningocele, meninges herniate but the spinal cord and roots remain within the canal.", "pdf_page": 1150, "printed_page": "1146"}, {"label": "Closed lesions", "text": "Closed dysraphism can tether neural tissue despite intact skin. Closed lesions include lipomyelomeningocele and other tethering disorders.", "pdf_page": 1150, "printed_page": "1146"}, {"label": "Risk-bearing skin findings", "text": "Investigate for underlying dysraphism; these are concerning stigmata. Multiple stigmata, lipomas and dermal sinuses are higher-risk findings in the source framework.", "pdf_page": 1152, "printed_page": "1148"}, {"label": "Age and imaging", "text": "Ossification of posterior elements reduces the ultrasound window. MRI offers detailed soft-tissue anatomy as ossification limits ultrasound access.", "pdf_page": 1153, "printed_page": "1149"}, {"label": "Open-defect protection", "text": "Protect the lesion with sterile covering and coordinate prompt specialist management. Exposed neural tissue and CSF create infection risk; sterile protection, indicated antimicrobial care and surgical coordination are central.", "pdf_page": 1154, "printed_page": "1150"}], "reader_html": "<section class=\"source-section\" data-pdf-page=\"1149\"><h2>PDF page 1149 · Printed 1145</h2><h3>Overview</h3><p>60 Spinal Dysraphisms</p><small class=\"source\">PDF p. 1149</small><h3>Summary</h3><p>This chapter reviews open and closed neural tube defects (NTDs). We discuss imaging evaluation as well as physical exam findings. Finally, we discuss current trends in treatment and perinatal care.</p><small class=\"source\">PDF p. 1149</small><h3>Introduction</h3><p>NTDs are the second-most common birth defect after congenital heart defects, affecting 1 to 2 in 1000 pregnancies worldwide. Spinal dysraphisms are a subset of NTDs and are classified as open or closed. The most common open spinal dysraphisms are meningocele and myelomeningocele. Closed spinal dysraphisms include a wider range of conditions, including spina bifida occulta, tethered cord, lipomyelomeningocele, split cord malformations, neuroenteric cysts, and several other conditions.1 Although open spinal dysraphisms are usually compatible with postnatal survival, they can result in severe neurologic impairment correlating with the level of the lesion: inability to ambulate, urinary incontinence, hydrocephalus, scoliosis, and gastrointestinal (GI) disorders. Closed spinal dysraphisms are often less severe and sometimes asymptomatic, but they can cause severe neurologic impairment secondary to spinal cord tethering.2 Given both the neurologic complexity and severity of these conditions, it is paramount to understanding the embryology, screening, management, and treatment to offer the best neurologic outcome for these patients.</p><small class=\"source\">PDF p. 1149</small><h3>Embryology</h3><p>Understanding the embryology of spinal dysraphisms has helped in making advancements to improve the technology used when treating patients with spinal dysraphisms. Spinal dysraphisms result from a failure of one of the following processes: gastrulation, primary neurulation, disjunction, or secondary neurulation. Gastrulation is the process by which the bilaminar embryonic disc becomes trilaminar: consisting of mesoderm, endoderm, and ectoderm. When gastrulation occurs, a neuroenteric canal forms, creating a temporary connection between the dorsal and ventral surfaces of the trilaminar disc. Conditions such as split cord</p><small class=\"source\">PDF p. 1149</small><p>malformations and neuroenteric cysts are thought to arise from a persistent neuroenteric canal. Neurulation begins with the notochord-inducing formation of the central nervous system (CNS) by signaling the ectodermal tissue to differentiate into the neuroectoderm and form the neural plate. The neural plate then folds inward until the edges of the plate contact one another, a process referred to as primary neurulation. Primary neurulation is thought to be initiated at multiple closure sites and proceed in a zipperlike fashion, bidirectionally. At the end of primary neurulation, the neural tube separates from the surface ectoderm in a process called disjunction. During disjunction, the mesoderm migrates between the surface ectoderm and neural tube, forming the meninges, vertebrae, skull, and paraspinal muscles. Premature or incomplete disjunction can lead to lipomyelomeningocele and dermal sinus, respectively. Secondary neurulation represents the formation of spinal cord caudal to the mid sacral region. During this process, multipotent cells come together to form a tail bud, which undergoes canalization to form the secondary neural tube.3 Open spinal dysraphisms result from a severe delay or cessation of the progression of primary neurulation along the body axis. When the neural fold does not close properly, the sclerotome is unable to cover the neuroepithelium, and a bifid vertebral canal results, leading to an open spinal dysraphism. Although unclear, it is believed that some closed spinal dysraphisms are a result of abnormalities of secondary neurulation, causing malformation of the lower sacral and coccygeal regions. This is thought to be the case because these dysraphisms do not open to the external environment, resulting in tethering of the spinal cord because of faulty tissue separation, and the cell types contained within these dysraphisms usually have multiple germ layers, owing to the multipotential nature of the tail bud formed in secondary neurulation.1</p><small class=\"source\">PDF p. 1149</small><p>Several signaling pathways and cellular functions are involved in the development of NTDs; these include planar cell polarity signaling (PCP), sonic hedgehog signaling (SHH), bone morphogenic signaling (BMP), grainyhead-like (GRHL) genes, retinoid signaling (RA), and many cellular functions such as apoptosis and cellular proliferation. Several factors are responsible that can increase the risk of developing neural tube defects and</p><small class=\"source\">PDF p. 1149</small></section><section class=\"source-section\" data-pdf-page=\"1150\"><h2>PDF page 1150 · Printed 1146</h2><h3>Embryology</h3><p>include both environmental and genetic factors. Environmental factors that affect the embryology of the CNS and lead to an increased risk of development of NTDs include valproic acid, fumonisin (a fungal product), carbamazepine, trimethoprim, folate or vitamin B12 deficiency, inositol, and maternal diabetes mellitus. Genetic factors include the C67TT and A1298C polymorphisms of the gene methylenetetrahydrofolate reductase, which result in a 1.8-fold increased risk of NTDs, and several modifier genes.1</p><small class=\"source\">PDF p. 1150</small><h3>Pathology</h3><p>Understanding the pathology of spinal dysraphisms is important in diagnosis and management, including both surgical and nonsurgical treatments. Spinal dysraphisms are typically divided into open and closed dysraphisms. Open dysraphisms include meningocele and myelomeningocele, whereas closed spinal dysraphisms include more diverse phenotypes (Table 60.1).</p><small class=\"source\">PDF p. 1150</small><h3>Open Spinal Dysraphisms</h3><p>Meningoceles are usually classified by location as either posterior lumbar, sacral, or thoracic; posterior cervical and limited dorsal myeloschisis; and anterior sacral. These lesions vary in size, are pedunculated, transilluminate well, and may be covered by cutaneous elements (Fig. 60.1). In meningoceles, the meninges herniate through a defect in the posterior vertebral arches, but the spinal cord remains in the spinal canal. Thus the spinal cord and nerve roots are normal in their structure and position in the spinal canal.4 Myelomeningocele represents 50% of all NTDs. It is often subdivided into spina bifida cystica and spina bifida aperta. In spina bifida cystica, there is an open spinal cord covered by a meningeal sac. In spina bifida aperta, the spinal cord is exposed (Fig. 60.2). Myelomeningocele-affected infants typically show neurologic deficits below the level of the lesion and may be associated with other conditions such as hydrocephalus, skeletal, renal, and GI disorders.2</p><small class=\"source\">PDF p. 1150</small><h3>Closed Spinal Dysraphisms</h3><p>Closed spinal dysraphisms are subdivided into categories based on whether a subcutaneous mass is present. Closed spinal dysraphisms consist of spina bifida occulta, lipomyelomeningocele, dorsal dermal sinus, split cord malformation, neuroenteric cyst, and several other conditions. They are often grouped into a generic term “tethered cord syndrome,” which more appropriately describes the constellation of symptoms that can be associated with these disorders.</p><small class=\"source\">PDF p. 1150</small><p>Spina bifida occulta is the mildest form of spina bifida and occurs when one or more vertebrae are split at the level of the spinous processes, but the spinal cord and corresponding nerve roots remain intact and in place. In this entity, the vertebral defect is covered by skin and can be associated with several cutaneous stigmata, including midline dimple, tuft of hair, change in skin coloration, sinus tract, and hemangiomatous lesion. Spina bifida occulta may be asymptomatic for years but can present later in life with varying degrees of neurologic compromise if associated with other closed dysraphisms.4</p><small class=\"source\">PDF p. 1150</small><p>Lipomyelomeningocele is a complex closed spinal dysraphism that usually occurs in the lumbar or sacral region. It is characterized by a subcutaneous lipoma that extends through the lumbosacral fascia, vertebral arches, and dura to attach to the spinal cord as a tethering mass (Fig. 60.3).</p><small class=\"source\">PDF p. 1150</small><figure class=\"source-page\"><a href=\"tables/ch060_page1150.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch060_page1150.jpg\" alt=\"Original source page 1150, including its figures or tables\"></a><figcaption>Original source-page view · PDF 1150. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"1151\"><h2>PDF page 1151 · Printed 1147</h2><h3>Closed Spinal Dysraphisms</h3><p>Given its association with spinal cord tethering, severe neurologic deterioration can result if left untreated. Nevertheless, because the subcutaneous fatty mass is usually evident at birth, patients are often diagnosed before neurologic symptoms develop, with as many as 48% of patients being neurologically intact at the time of initial diagnosis. Spinal lipomas differ in that the lipoma does not extend through the lumbar fascia and typically remains encased within the spinal canal. The various forms of lipomas are categorized into three types that are defined by their anatomic attachment to the spinal cord: dorsal, transitional, and caudal (or chaotic).5 In the dorsal type, there is an attachment of the lipoma to the dorsal spinal cord at the level of myeloschisis, or neural placode. The transitional type has a lipomatous attachment that extends beyond the level of myeloschisis down to the conus medullaris and may involve the nerve roots. The caudal type has a lipomatous attachment, which arises from the caudal end of the conus medullaris, often encasing the nerve roots. Patients with lipomyelomeningocele have both a congenital malformation of their spinal cord as well as a risk of retethering their spinal cord after release because of scarring. These patients may develop neurogenic bladder or bowel, orthopedic deformities, scoliosis, and spasticity as a result of their tethered cord.6</p><small class=\"source\">PDF p. 1151</small><p>Dorsal dermal sinus is a rare spinal dysraphism that involves a tract lined by epithelium that traverses a variable depth, usually terminating in or on the thecal sac (Fig. 60.4). This type of closed dysraphism is usually seen at the extremes of the neuraxis and may be associated with lifethreatening infections, such as meningitis from bacteria tracking into the cerebrospinal fluid space. It can be associated with symptoms of a tethered cord, diastematomyelia, and inclusion cysts. Thus, despite the benign external appearance of this dysraphism, it can result in neurologic deficit and harbor great risks for patients if not addressed in a timely manner.7</p><small class=\"source\">PDF p. 1151</small><p>Diastematomyelia is commonly referred to as split cord malformation and describes a phenomenon in which the</p><small class=\"source\">PDF p. 1151</small><p>spinal cord is split into two hemicords with each hemicord having its own set of ventral and dorsal nerve roots. They may be encased in a single dural sac, or the dural sac may be split at the level of the dysraphism. In addition, a fibrous or bony septum may be present between the hemicords. Frequently, the conus medullaris is low lying and tethered by a thickened filum terminale. This dysraphism can be associated with other dysraphisms such as myelomeningoceles and neuroenteric cyst. There is also a high instance of bony vertebral column abnormalities with split cord malformations, including butterfly vertebra, a widened spinal canal, fusion of pedicles, or failure of vertebral body segmentation. Neuroenteric cysts are closely associated with split cord malformation, and they often occur together because they both occur because of errors in gastrulation. Neuroenteric cysts occur most frequently at the lower cervical or upper thoracic regions and at the conus medullaris. These cysts can be extra- or intradural and, if intradural, can be anterior, posterior, or within the spinal cord.8,9</p><small class=\"source\">PDF p. 1151</small><p>An abnormal filum terminale is the mildest form of a closed dysraphism, which can result in a tethered spinal cord. A filum is considered thickened when it is greater than 2 mm in diameter and contains an increased amount of connective tissue or fat with a low-lying conus medullaris. Similar to the other forms of closed spinal dysraphisms, these patients may be at risk of developing tethered cord syndrome and, if untreated, developing neurogenic bladder or lower extremity issues.4</p><small class=\"source\">PDF p. 1151</small><figure class=\"source-page\"><a href=\"tables/ch060_page1151.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch060_page1151.jpg\" alt=\"Original source page 1151, including its figures or tables\"></a><figcaption>Original source-page view · PDF 1151. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"1152\"><h2>PDF page 1152 · Printed 1148</h2><h3>Prenatal Screening And Prevention</h3><p>In the early 1970s, maternal serum screening for fetal congenital malformations began with the advent of alpha-fetoprotein (AFP) screening for NTDs. Today, screening has evolved with highly complex protocols using cell-free DNA markers. However, AFP levels still represent the mainstay of screening for open NTDs. Maternal serum AFP screening is conducted between 15 and 21 weeks of gestation. Median maternal serum AFP levels increase steadily from 15 to 21 weeks’ gestation. To account for the upward trend in maternal AFP that occurs in pregnancy, values are converted into multiples of the gestational age-specific median (multiples of the median [MoMs]). The typical cutoff for maternal serum AFP screening is 2.0 to 2.5 MoM, but using a cutoff of 2.0 MoM increases detection of open spina bifida by 10%. This cutoff brings the specificity for open spina bifida cases to 90% and the sensitivity for anencephaly to 100% for the maternal serum AFP assay. Patients with elevated maternal serum AFP can opt to have amniocentesis to increase the likelihood of detection.10 The amniotic fluid AFP level is then tested, and elevations along with a positive acetylcholinesterase confirmation test can detect 96% of open spina</p><small class=\"source\">PDF p. 1152</small><p>bifida cases. Ultrasound can also be used as a screening tool to detect open NTDs, with a sensitivity of 97% and specificity of 100% in the hands of an experienced sonographer.11</p><small class=\"source\">PDF p. 1152</small><p>Risk of NTDs in humans is increased with folic acid deficiency and exposure of the embryo to excessive retinoic acid or vitamin A. Several studies have shown that 70% of NTDs can be prevented by preconception folic acid supplementation of 0.4 mg/day.12 Mothers with one affected infant are at a higher risk than the general population for a second affected infant and should take 4 mg/day of folic acid before and during subsequent pregnancies.</p><small class=\"source\">PDF p. 1152</small><h3>Cutaneous Stigmata</h3><p>Cutaneous stigmata are commonly found in closed spinal dysraphisms because the skin and nervous system share an intimate embryologic origin. Recognition of cutaneous stigmata commonly associated with closed spinal dysraphisms is important because early identification and intervention may prevent irreversible neurologic damage associated with tethered cord syndrome. Cutaneous stigmata are found in 4.2% to 7.2% of all neonates with closed spina bifida, and the presence of two or more cutaneous stigmata has a high predictive value of a closed spinal dysraphism. Additionally, there should also be a high suspicion for closed spinal dysraphism when cutaneous stigmata occur in combination with anogenital or urogenital malformations. When assessing patients with cutaneous lumbosacral stigmata, it is important to recognize concerning features; thus these stigmata are typically separated into high-, intermediate-, and lowrisk categories. High-risk cutaneous findings include two or more cutaneous lumbosacral stigmata, infantile hemangiomas greater than 2.5 cm, dermoid cyst or sinus, lipoma, acrochordon, pseudotail, true tail, aplasia cutis, and congenital scars. Intermediate-risk cutaneous findings include atypical dimple (&gt;5 mm in diameter or &gt;2.5 cm from anal verge), infantile hemangioma less than 2.5 cm, and hypertrichosis. Low-risk cutaneous findings include simple dimple, hyper- or hypopigmentation, melanocytic nevi, teratomas, port-wine stain, or telangiectasias (Table 60.2). Based on the risk category, certain imaging modalities are recommended. MRI is recommended for all high-risk cutaneous findings. For intermediate-risk cutaneous finding, ultrasound is recommended for those less than 6 months and MRI for those greater than 6 months. Lastly, most cases of low-risk cutaneous stigmata do not require imaging; if overly concerned, an ultrasound can be performed.3</p><small class=\"source\">PDF p. 1152</small><h3>Imaging</h3><p>The two major imaging modalities used to confirm and characterize spinal dysraphisms are spinal ultrasonography and MRI. Ultrasound is possible in newborns and in early infancy before 6 months of age because of the lack of ossification of the predominantly cartilaginous posterior elements of the spine. Spinal ultrasound can sometimes be performed after 6 months if a persistent posterior</p><small class=\"source\">PDF p. 1152</small><figure class=\"source-page\"><a href=\"tables/ch060_page1152.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch060_page1152.jpg\" alt=\"Original source page 1152, including its figures or tables\"></a><figcaption>Original source-page view · PDF 1152. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"1153\"><h2>PDF page 1153 · Printed 1149</h2><h3>Imaging</h3><p>spinal defect is present. However, as the posterior elements ossify, the quality of ultrasound images decreases. MRI is extremely useful in the evaluation of pediatric spinal anomalies. Given the resolution provided by MRI of the soft tissues, it allows for improved diagnosis of spinal dysraphisms and has enhanced the possibility of earlier and case-tailored treatment, especially in the case of complex dysraphisms where there may be rotation of the neural elements. Thus MRI is the gold standard for imaging spinal dysraphisms.13</p><small class=\"source\">PDF p. 1153</small><p>Ultrasonography is widely used today for prenatal screening for spinal dysraphism. It represents a cost-effective imaging modality for diagnosing and treating spinal anomalies in utero. High-resolution ultrasonography offered today can accurately localize the site of osseous and soft tissue defects. This has made it possible to accurately diagnose conditions such as myelomeningocele, lipomyelomeningocele, and diastematomyelia in utero. During the second trimester fetal anatomic survey, it is important to visualize the longitudinal, sagittal, coronal, and axial images of the spine. This allows for a complete view of the spine to analyze for spinal anomalies. If the transabdominal scan is not optimal, transvaginal scans are done to evaluate the spine. In addition to localization of the conus medullaris and spinal defects, it is important to measure any visualized sacs, especially if in utero repair is planned, because larger defects may require tissue matrix for closure.14 The components of any visualized sac are analyzed to determine the presence of neural elements, which appear as linear echogenic areas surrounded by anechoic cerebrospinal fluid. The neural placode of the myelomeningocele can also be visualized and appears as a hypoechoic, ovoid region within the sac.15 The wall of the myelomeningocele is also assessed on the ultrasound and characterized as thin or thick. The accuracy of ultrasonography varies greatly and depends on operator experience, maternal obesity, fetal movement, and fetal positioning. Nevertheless, correct identification of spinal anomalies and associated CNS and non-CNS abnormalities has been reported to have a sensitivity rate of 97% and a specificity rate of 100%.16,17</p><small class=\"source\">PDF p. 1153</small><p>MRI is a useful adjunct imaging modality in the fetus, infants, and children for detecting and further characterizing spinal anomalies. The high resolution of the soft tissues offered by this imaging modality can provide</p><small class=\"source\">PDF p. 1153</small><p>better visualization and more understanding of patientspecific pathology before surgical intervention. It is useful in detecting the degree of hindbrain herniation before repair and evaluating both brain and spinal cord anatomy when ultrasound is limited. Fetal MRI is important to obtain when in utero repair of spinal dysraphism is being considered. If good-quality images are able to be obtained prenatally, it may eliminate the need for postnatal images, which often require sedation to obtain a quality image.18–20</p><small class=\"source\">PDF p. 1153</small><h3>Overall Management</h3><p>Spinal NTDs can cause a wide variety of presentations and neurologic deficits. Thus it is of the utmost importance to properly manage these patients to improve their neurologic outcome and prevent infection in open spinal defects. The urgency and timing of intervention differ greatly between open and closed spinal dysraphism. Open spinal dysraphism requires more urgent management and intervention because the neural tissue and cerebrospinal fluid are directly exposed to the outside environment, predisposing these children to infections such as meningitis. Myelomeningocele is one of the most morbid and debilitating of the open spinal NTDs. It can cause severe neurologic deficit, hydrocephalus, and meningitis in the postnatal period. Although some centers repair myelomeningoceles in utero during the prenatal period (see also Chapter 12), postnatal repair of myelomeningoceles remains the standard of care. Nevertheless, no specific guidelines exist regarding the management of these conditions. Although each institution may differ in how they manage myelomeningocele, the overall premise of management remains the same.21</p><small class=\"source\">PDF p. 1153</small><p>When myelomeningocele is diagnosed in utero, the first issue that arises is the mode of delivery. Many institutions advocate for cesarean section before labor when compared with vaginal delivery or cesarean section after labor. Some studies have shown improved motor function at 2 years of age in patients delivered via cesarean section before labor when compared with any mode of delivery after labor. Other studies have shown that once labor commences, there is no change in outcome based on mode of delivery. Given the impact upon the mother, if a cesarean section is recommended, this is often a discussion between the obstetrician</p><small class=\"source\">PDF p. 1153</small><figure class=\"source-page\"><a href=\"tables/ch060_page1153.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch060_page1153.jpg\" alt=\"Original source page 1153, including its figures or tables\"></a><figcaption>Original source-page view · PDF 1153. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"1154\"><h2>PDF page 1154 · Printed 1150</h2><h3>Overall Management</h3><p>and the neurosurgeon in the prenatal period that takes into consideration the presence or absence of hydrocephalus, which may preclude a vaginal delivery if the head size is too large. After the fetus is delivered, focus turns to prevention of infection, including prophylactic antibiotics, maintaining the sterility of the open dysraphism with sterile coverings, and timing of intervention.22,23</p><small class=\"source\">PDF p. 1154</small><p>After delivery of the fetus, the size and location of the lesion should be noted. The lesion should also be assessed for leaking of cerebrospinal fluid. When assessing the lesion, sterile, nonlatex gloves are recommended to minimize the risk of latex sensitization.24,25 The defect should be covered with a sterile, saline-soaked dressing. Larger defects should be covered by a plastic wrap to prevent heat loss. The infant should also be placed in a prone or lateral position to avoid prolonged pressure on the lesion.26 A thorough neurologic examination should also be performed with the objective of defining the baseline neuropathology of the patient, paying attention to the observation of spontaneous activity, extent of muscle weakness, leg posture and paralysis, response to sensation, deep tendon reflexes, and anocutaneous reflex for assessment of spinal cord function. The functional level of the lesion is as important as the anatomic level, because there may not be an exact correlation depending on the functionality of the exposed neural tissue (Table 60.3). The newborn should also be evaluated for club feet and flexion or extension of the hips, knees, or ankles because this helps to define the level of the lesion. In addition, one should evaluate for signs of hydrocephalus, including a measurement of head circumference, assessment of the fontanelle and sutures for signs of splaying or fullness, and signs of brainstem compression from a Chiari II malformation. Concerning signs of apnea or bradycardia, lower brainstem dysfunction may be an indication to treat the hydrocephalus, and persistence of symptoms after treatment is a poor prognostic sign (Table 60.4). The spinal column may demonstrate kyphosis, and assessment should include evaluation for other congenital anomalies involving the heart, airway, kidneys, or GI tract.</p><small class=\"source\">PDF p. 1154</small><p>Although there is no consensus for the specific type of prophylactic antibiotic used in these patients, the agents often used are ampicillin in addition to either gentamycin or cefotaxime. This provides coverage for group B streptococcus and gram-negative bacteria. Antibiotics should be started within 1 hour of birth and continued for at least 48 hours after repair. Prophylactic antibiotics and wound sterility greatly reduce the risk of early CNS infection, but timely repair of the defect also significantly reduces the risk of CNS infection.27 Postnatal repair should be performed within 48 to 72 hours after birth.1,21,28 However, most would advocate closure within 24 to 48 hours. Postoperatively, patients should remain in the prone or lateral position to avoid pressure on the incision and allow for wound healing. Close attention should also be placed to prevent urine or feces from entering the wound, and bumpers with drapes are often used between the wound and diaper to prevent diaper contents from affecting the wound and causing an infection. Given the high risk of hydrocephalus in this patient population, the infant should be monitored for signs and symptoms of hydrocephalus and at the very least get daily head circumference measurements and weekly head ultrasounds.21</p><small class=\"source\">PDF p. 1154</small><p>Closed spinal dysraphism management is less urgent than open spinal dysraphisms. This is because the defect is covered</p><small class=\"source\">PDF p. 1154</small><figure class=\"source-page\"><a href=\"tables/ch060_page1154.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch060_page1154.jpg\" alt=\"Original source page 1154, including its figures or tables\"></a><figcaption>Original source-page view · PDF 1154. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"1155\"><h2>PDF page 1155 · Printed 1151</h2><h3>Overall Management</h3><p>by skin and not directly exposed to the outside environment. Thus prophylactic antibiotics are not needed for these conditions, with the potential exception being dermal sinus tracts that have direct extension into the thecal sac and an opening at the skin. Nevertheless, thorough neurologic examination should be performed in these patients to assess for any neurologic deficit given the close association with tethered spinal cord. A thorough cutaneous examination should also be performed to look for cutaneous stigmata for a subcutaneous fatty mass as in the case of lipomyelomeningocele. MRI of the entire spine is recommended for patients who have two or more cutaneous lumbosacral spine lesions, a subcutaneous back mass, or neurologic symptoms concerning tethered cord syndrome. MRI or ultrasound is also recommended for patients with isolated midline cutaneous lumbosacral spine lesions. Patients with radiographically confirmed closed spinal dysraphism should be referred to neurosurgery for an evaluation. Surgery in these cases is nonurgent and is usually performed more urgently in patients with neurologic deficits in the setting of a tethered cord. Conservative management with observation is reasonable for patients who are asymptomatic from a closed spinal dysraphism, although surgery may be considered as a prophylactic means of treatment because of the high risk of neurologic deterioration and potential for irreversible neurologic injury.2,6</p><small class=\"source\">PDF p. 1155</small><h3>Surgical Treatment</h3><p>Open spinal dysraphisms require timely surgical intervention to reduce the risk of early CNS infection and further neurologic decline. Myelomeningocele, the most common open spinal dysraphism, can be treated either pre- or postnatally, although postnatal treatment still represents the standard of care. The Management of Myelomeningocele Study (MOMS) was a randomized study of 183 patients at several pediatric centers across the United States comparing prenatal to postnatal repair of myelomeningocele and published in 2011. Patients were randomly assigned to undergo either prenatal repair of the myelomeningocele before 26 weeks’ gestation or standard postnatal repair. The primary endpoints of the study included fetal or neonatal death, need for shunt at 12 months, as well as mental development and motor function at 30 months. Of the 183 patients enrolled, 158 patients were evaluated at 12 months, and results showed that only 40% of patients required a shunt after prenatal repair compared with 82% in the postnatal group. The study also showed that the prenatal group had improved mental and motor development at 30 months when compared with the postnatal group. Secondary outcomes, such as hindbrain herniation and ambulation at 30 months, were also improved in the prenatal group.29 Although the study offered promising results, enrollment was stopped because of efficacy secondary to increased risk of preterm delivery and uterine dehiscence at delivery. In addition, the population of mothers who were able to enroll in the study because of the location restrictions associated with fetal repair narrowed the applicable population of both</p><small class=\"source\">PDF p. 1155</small><p>appropriate maternal candidates and size and location of lesion. The follow-up to MOMS, MOMS II, followed the prenatal versus postnatal surgery groups into school age with the primary outcome measure of Vineland composite score between the groups. The study found no significant difference between the two groups at school age regarding their Vineland Composite Score or adaptive behavior. However, the follow-up study found that parents in the prenatal group reported reduced negative social and family impact in addition to the continued benefits found in MOMS, such as improvement in motor and neurologic outcomes.30 Since the trials, other centers have started performing fetoscopic repair; however, these results are not widespread yet. Given the risks of prenatal repair as well as that these interventions are occurring at limited centers, postnatal repair still represents the standard of care for treatment. Repair is usually performed in a timely manner, between 24 and 48 hours, and involves approximation of the lateral edges of the open neural plate in the midline to form a neural tube, closure of a meningeal sac, and closure of the skin over the open defect. Although there is no evidence to support neural tube closure, it is thought that reforming the neural tube reduces the incidence of tethered spinal cord by reducing the raw edge at risk of scarring. The most common condition to develop after repair is hydrocephalus, and infants must be monitored closely with head circumferences and head ultrasounds. Upward of 60% to 80% of infants with myelomeningocele develop hydrocephalus and require placement of shunt.31 Other conditions that require monitoring and possible treatment in this patient population include Chiari II malformation, tethered cord, shunt malfunction, neurogenic bladder and bowel, and several orthopedic deformities.1</p><small class=\"source\">PDF p. 1155</small><p>Closed spinal dysraphism is amenable to a delay in surgical intervention when compared with the open dysraphism, because the defect is not exposed to the external environment. Surgical treatment is often required for infants with tethered cord syndrome with a neurologic deficit, because some patients can be asymptomatic from their closed spinal dysraphism. Surgical treatment involves removal of the subcutaneous mass (if any), identification of the defect and release of the tethered, possible release of the filum terminale, preservation of neural elements, and prevention of retethering of the spinal cord. Given the complexity of the surgery for NTDs, surgery is not without significant risks. Common risks of surgical intervention include neurologic decline from tethered cord or secondary to nerve injury during the surgery, incomplete wound healing or wound dehiscence, infection, and meningitis. Patients with lipomyelomeningocele have a complication rate between 10% and 30%, a 5.8% risk of worse neurologic function after surgery, and between a 10% and 20% risk of retethering postoperatively.6</p><small class=\"source\">PDF p. 1155</small><h3>Fetal Repair Of Myelomeningocele</h3><p>Surgically treating myelomeningocele postnatally is still considered the standard of care. However, with studies</p><small class=\"source\">PDF p. 1155</small></section><section class=\"source-section\" data-pdf-page=\"1156\"><h2>PDF page 1156 · Printed 1152</h2><h3>Fetal Repair Of Myelomeningocele</h3><p>showing the benefits of intrauterine closure of myelomeningocele and advances in surgical techniques, prenatal surgical treatment is worth a more thorough discussion.</p><small class=\"source\">PDF p. 1156</small><p>The benefit of intrauterine repair of myelomeningocele begins with the idea of the two-hit theory. The two-hit theory suggests that the first neurological injury occurs immediately at the time of failure of neural tube closure, and the second hit occurs because of the neural tissue being in contact with intrauterine contents, hydrodynamic pressures, or even direct trauma.32 As a result of the two-hit theory, intrauterine repair of myelomeningocele can reduce the second “hit” and improve neurological outcomes.30</p><small class=\"source\">PDF p. 1156</small><p>In general, two surgical techniques are used for intrauterine repair of myelomeningocele: open and endoscopic. The open technique begins with an incision from the pubis to just above the umbilicus. The fetus and placenta are then localized using sonography, and a 6- to 8-cm hysterotomy is created. The neural placode, or malformed spinal cord, is then sharply incised to allow the neural elements to fall into the spinal canal. The dura is then closed in a watertight fashion, or synthetic dura can be used for help with closure. The last step is then tensionless closure of the skin.33 Endoscope repair has been forced to evolve over the years because of its difficulty with visualization along with a small working field. Endoscope repair began in the early 2000s by laying a synthetic patch over the defect to protect the neural</p><small class=\"source\">PDF p. 1156</small><p>Key Points</p><small class=\"source\">PDF p. 1156</small><p>• Spinal dysraphisms include both open and closed defects</p><small class=\"source\">PDF p. 1156</small><p>with varying degrees of neurologic impairment. • Open defects include meningocele and myelomenin-</p><small class=\"source\">PDF p. 1156</small><p>gocele, which may be repaired prenatally but more commonly are repaired postnatally and warrant urgent surgical repair and perinatal antibiotic prophylaxis to prevent meningitis. • Monitoring for signs of infection, hydrocephalus, and</p><small class=\"source\">PDF p. 1156</small><p>symptoms of a Chiari II malformation is critical in the perinatal period.</p><small class=\"source\">PDF p. 1156</small><h3>References</h3><p>elements, then doing a formal skin closure in the postnatal setting. Recent advances in techniques have included both laying on the synthetic patch and attempting a single-layer skin closure through endoscopy.33 Both techniques have risk regarding both the fetus and the mother. The effectiveness of one versus the other is dictated not only by the surgical equipment used but also by the experience and expertise of the surgeon. Pediatric neurosurgeons are constantly modifying the techniques in the hope of reducing limitations and complications for both the mother and the patient.</p><small class=\"source\">PDF p. 1156</small><h3>Conclusion</h3><p>Spinal NTDs are a diverse group of congenital spinal anomalies and can result in severe neurologic outcomes. These conditions range from open spinal dysraphisms, which require prompt delivery, ICU management, and surgical intervention, to closed spinal dysraphism, which may initially be asymptomatic, and can be treated in a delayed fashion. These infants may have other severe conditions that can require complex management in the neonatal ICU. Thus it is paramount for clinicians to understand the embryology, pathogenesis, physical examination findings, management, and treatment to provide the optimal care for these patients in the ICU.</p><small class=\"source\">PDF p. 1156</small><p>• Closed spinal dysraphisms may be amenable to delayed</p><small class=\"source\">PDF p. 1156</small><p>treatment to prevent neurologic decline from a tethered spinal cord. • Fetal repair of myelomeningocele has been proven to be</p><small class=\"source\">PDF p. 1156</small><p>beneficial but is limited in its practice because of the high maternal risk as well as a steep learning curve and limited availability.</p><small class=\"source\">PDF p. 1156</small></section><section class=\"source-section\" data-pdf-page=\"1157\"><h2>PDF page 1157 · Printed 1153</h2><h3>Conclusion</h3><p>14. Meller C, Aiello H, Otano L. Sonographic detection of open</p><small class=\"source\">PDF p. 1157</small><p>spina bifida in the first trimester: review of the literature. Childs Nerv Syst. 2017;33(7):1101–1106. 15. Bulas D. Fetal evaluation of spine dysraphism. Pediatr Radiol.</p><small class=\"source\">PDF p. 1157</small><p>2010;40(6):1029–1037. 16. Carreras E, Maroto A, Illescas T, et al. Prenatal ultrasound evalu-</p><small class=\"source\">PDF p. 1157</small><p>ation of segmental level of neurological lesion in fetuses with myelomeningocele: development of a new technique. Ultrasound Obstet Gynecol. 2016;47(2):162–167. 17. Coleman BG, Langer JE, Horii SC. The diagnostic fea-</p><small class=\"source\">PDF p. 1157</small><p>tures of spina bifida: the role of ultrasound. Fetal Diagn Ther. 2015;37(3):179–196. 18. Badve CA, Khanna PC, Phillips GS, et al. MRI of closed spinal</p><small class=\"source\">PDF p. 1157</small><p>dysraphisms. Pediatr Radiol. 2011;41(10):1308–1320. 19. Nagaraj UD, Bierbrauer KS, Peiro JL, Kline-Fath BM. Differen-</p><small class=\"source\">PDF p. 1157</small><p>tiating closed versus open spinal dysraphisms on fetal MRI. AJR Am J Roentgenol. 2016;207(6):1316–1323. 20. Egloff A, Bulas D. Magnetic resonance imaging evaluation of fetal</p><small class=\"source\">PDF p. 1157</small><p>neural tube defects. Semin Ultrasound CT MR. 2015;36(6):487– 500. 21. Cavalheiro S, da Costa MDS, Moron AF, Leonard J. Com-</p><small class=\"source\">PDF p. 1157</small><p>parison of prenatal and postnatal management of patients with myelomeningocele. Neurosurg Clin N Am. 2017;28(3):439–448. 22. Brown SD, Feudtner C, Truog RD. Prenatal decision-making for</p><small class=\"source\">PDF p. 1157</small><p>myelomeningocele: can we minimize bias and variability? Pediatrics. 2015;136(3):409–411. 23. Greene S, Lee PS, Deibert CP, et al. The impact of mode of deliv-</p><small class=\"source\">PDF p. 1157</small><p>ery on infant neurologic outcomes in myelomeningocele. Am J Obstet Gynecol. 2016;215(4): 495.e491–495.e411.</p><small class=\"source\">PDF p. 1157</small><p>24. Cremer R, Kleine-Diepenbruck U, Hoppe A, Blaker F. Latex</p><small class=\"source\">PDF p. 1157</small><p>allergy in spina bifida patients--prevention by primary prophylaxis. Allergy. 1998;53(7):709–711. 25. Rendeli C, Nucera E, Ausili E, et al. Latex sensitisation and</p><small class=\"source\">PDF p. 1157</small><p>allergy in children with myelomeningocele. Childs Nerv Syst. 2006;22(1):28–32. 26. McLone DG. Care of the neonate with a myelomeningocele.</p><small class=\"source\">PDF p. 1157</small><p>Neurosurg Clin N Am. 1998;9(1):111–120. 27. Charney EB, Melchionni JB, Antonucci DL. Ventriculi-</p><small class=\"source\">PDF p. 1157</small><p>tis in newborns with myelomeningocele. Am J Dis Child. 1991;145(3):287–290. 28. Burke R, Liptak GS; Council on Children with Disabilities.</p><small class=\"source\">PDF p. 1157</small><p>Providing a primary care medical home for children and youth with spina bifida. Pediatrics. 2011;128(6):e1645–1657. 29. Adzick NS, Thom EA, Spong CY, et al. A randomized trial of</p><small class=\"source\">PDF p. 1157</small><p>prenatal versus postnatal repair of myelomeningocele. N Engl J Med. 2011;364(11):993–1004. 30. Houtrow AJ, Thom EA, Fletcher JM, et al. Prenatal repair of</p><small class=\"source\">PDF p. 1157</small><p>myelomeningocele and school-age functional outcomes. Pediatrics. 2020;145(2). 31. Talamonti G, D’Aliberti G, Collice M. Myelomeningocele: long-</p><small class=\"source\">PDF p. 1157</small><p>term neurosurgical treatment and follow-up in 202 patients. J Neurosurg. 2007;107(suppl 5):368–386. 32. Hutchins GM, Meuli M, Meuli-Simmen C, et al. Acquired spi-</p><small class=\"source\">PDF p. 1157</small><p>nal cord injury in human fetuses with myelomeningocele. Pediatr Pathol Lab Med. 1996;16(5):701–712. 33. Dewan MC, Wellons JC. Fetal surgery for spina bifida. J Neuro-</p><small class=\"source\">PDF p. 1157</small><p>surg Pediatr. 2019;24(2):105–114.</p><small class=\"source\">PDF p. 1157</small></section>", "guided": {"num": 60, "title": "Spinal Dysraphisms", "hook": "A small lumbosacral skin finding may be a surface clue to a deeper developmental lesion.", "audience": "Pediatric residents, neonatal fellows and clinicians studying the source edition", "prerequisites": "Core neonatal physiology and clinical assessment; foundational chapters support entry-level review.", "estimated_minutes": 25, "estimated_minutes_note": "Planning estimate for five units and feedback; full reference reading takes longer.", "lessons": [{"id": "L060-1", "objective_id": "O060-1", "objective": "Distinguish meningocele from myelomeningocele", "title": "Contents of a spinal sac", "level": "Essentials", "text": "Meningocele. In meningocele, meninges herniate but the spinal cord and roots remain within the canal.", "card_id": "fc-060-1", "question_id": "q-060-1", "pdf_page": 1150, "printed_page": "1146"}, {"id": "L060-2", "objective_id": "O060-2", "objective": "Recognize that skin coverage does not guarantee normal neural anatomy", "title": "Closed lesions", "level": "Clinical Application", "text": "Closed dysraphism can tether neural tissue despite intact skin. Closed lesions include lipomyelomeningocele and other tethering disorders.", "card_id": "fc-060-2", "question_id": "q-060-2", "pdf_page": 1150, "printed_page": "1146"}, {"id": "L060-3", "objective_id": "O060-3", "objective": "Identify cutaneous clues requiring further assessment", "title": "Risk-bearing skin findings", "level": "Clinical Application", "text": "Investigate for underlying dysraphism; these are concerning stigmata. Multiple stigmata, lipomas and dermal sinuses are higher-risk findings in the source framework.", "card_id": "fc-060-3", "question_id": "q-060-3", "pdf_page": 1152, "printed_page": "1148"}, {"id": "L060-4", "objective_id": "O060-4", "objective": "Explain why ultrasound windows change in infancy", "title": "Age and imaging", "level": "Clinical Application", "text": "Ossification of posterior elements reduces the ultrasound window. MRI offers detailed soft-tissue anatomy as ossification limits ultrasound access.", "card_id": "fc-060-4", "question_id": "q-060-4", "pdf_page": 1153, "printed_page": "1149"}, {"id": "L060-5", "objective_id": "O060-5", "objective": "Prioritize early management of exposed neural tissue", "title": "Open-defect protection", "level": "Clinical Application", "text": "Protect the lesion with sterile covering and coordinate prompt specialist management. Exposed neural tissue and CSF create infection risk; sterile protection, indicated antimicrobial care and surgical coordination are central.", "card_id": "fc-060-5", "question_id": "q-060-5", "pdf_page": 1154, "printed_page": "1150"}], "unavailable_levels": ["Deep Dive"], "review_status": "Model checked selected cited source passages; not specialist review", "case": null}});
